 }

-const store = new Map<string, Entry>();
+const STORE_PATH = path.join(process.cwd(), ".session-cache.json");
+let store = new Map<string, Entry>();
+
+function loadStore(): void {
+  try {
+    if (fs.existsSync(STORE_PATH)) {
+      const data = JSON.parse(fs.readFileSync(STORE_PATH, "utf-8"));
+      store = new Map(data);
+    }
+  } catch (err) {
+    console.warn("Failed to load session cache:", err);
+    store = new Map();
+  }
+}
+
+function saveStore(): void {
+  try {
+    fs.writeFileSync(STORE_PATH, JSON.stringify([...store.entries()]));
+  } catch (err) {
+    console.warn("Failed to save session cache:", err);
+  }
+}
+
+loadStore();

 export const put = (key: string, value: string, ttlMs: number): void => {
   store.set(key, { value, expiresAt: Date.now() + ttlMs });
